                    {project.status}
                  </span>
                </div>

                <div className="flex items-center gap-2 mt-2 text-xs text-white/40">
                  <span>{typeIcon[project.type]}</span>
                  <span>{project.type}</span>
                  <span>•</span>
                  <span>{formatDate(project.createdAt)}</span>
                </div>

                {/* Actions */}
